import React, { useState } from 'react';

export default function SimpleSearch() {
  const names = ["Alice", "Bob", "Charlie"];
  const [search, setSearch] = useState("");

  const filtered = names.filter(n => n.toLowerCase().includes(search.toLowerCase()));

  return (
    <div>
      <input placeholder="Search name" onChange={e => setSearch(e.target.value)} />
      <ul>
        {filtered.map(name => <li key={name}>{name}</li>)}
      </ul>
    </div>
  );
}

import React, { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <h2>Count: {count}</h2>
      <button onClick={() => setCount(count + 1)}>+1</button>
      <button onClick={() => setCount(count - 1)}>-1</button>
    </div>
  );
}

import React, { useState } from 'react';

export default function Todo() {
  const [tasks, setTasks] = useState(["Learn HTML", "Learn React"]);
  const [text, setText] = useState("");

  const add = () => {
    if (text) {
      setTasks([...tasks, text]);
      setText("");
    }
  };

  return (
    <div>
      <input value={text} onChange={e => setText(e.target.value)} />
      <button onClick={add}>Add Task</button>
      <ul>
        {tasks.map((t, index) => <li key={index}>{t}</li>)}
      </ul>
    </div>
  );
}

